export function invite(emails) {
  return emails.map((email) => {
    const e = String(email).trim().toLowerCase();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) || e.length > 254) return { email, sent: false };
    return { email: e, sent: true };
  });
}

