import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { isValidEmail } from '../email.js';
import { signup } from '../signup.js';
import { invite } from '../invite.js';
test('validator', () => { assert.equal(isValidEmail(' A@B.co '), true); assert.equal(isValidEmail('nope'), false); assert.equal(isValidEmail('a@' + 'b'.repeat(260) + '.com'), false); });
test('behaviour kept', () => {
  assert.deepEqual(signup(' Dee@Mail.com ', 'longenough'), { ok: true, email: 'dee@mail.com' });
  assert.deepEqual(signup('x', 'longenough'), { ok: false, error: 'bad email' });
  assert.deepEqual(signup('a@b.co', 'short'), { ok: false, error: 'short password' });
  assert.deepEqual(invite(['a@b.co', 'bad']), [{ email: 'a@b.co', sent: true }, { email: 'bad', sent: false }]);
});
test('no duplicate regex left', () => {
  for (const f of ['signup.js', 'invite.js']) assert.ok(!readFileSync(new URL('../' + f, import.meta.url), 'utf8').includes('[^\\s@]'), f + ' still has its own regex');
});

solution.email.js:
export function isValidEmail(email) {
  const e = String(email).trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) && e.length <= 254;
}

solution.signup.js:
import { isValidEmail } from './email.js';
export function signup(email, password) {
  if (!isValidEmail(email)) return { ok: false, error: 'bad email' };
  if (String(password).length < 8) return { ok: false, error: 'short password' };
  return { ok: true, email: String(email).trim().toLowerCase() };
}

solution.invite.js:
import { isValidEmail } from './email.js';
export function invite(emails) {
  return emails.map((email) => (isValidEmail(email) ? { email: String(email).trim().toLowerCase(), sent: true } : { email, sent: false }));
}
